            final_choices = []
            for idx in chosen_indices:
                bag_max = max(random_bag[idx]) if random_bag[idx] else float('-inf')
                if bag_max > max_max:
                    max_max = bag_max
                    final_choices = [idx]
                elif bag_max == max_max:
                    final_choices.append(idx)
            chosen_bag = min(final_choices)  # pick lowest index if still tied
        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=chosen_bag, type='custom')]
        )
